    let depth = 1;
    for (let i = end - 2; i >= 0; i--) {
        const c = s[i];
        if (c === ")") {
            depth++;
            continue;
        }
        if (c !== "(") {
            continue;
        }
        depth--;
        if (depth === 0) {
            return { open: i, innerStart: i + 1, innerEnd: end - 1 };
        }
    }
    return null;
}
