    const end = trimTrailingSpaceAndPeriod(s);
    if (end === 0 || s[end - 1] !== ")") {
        return null;
    }
    return matchingOpenParen(s, end);
}
/** Turn a `[label](path#Lline)` regex match into a normalized link ref. */
function linkRefFromMatch(match) {
    const label = match[1].replace(/\s+/g, " ").trim();
